#!/usr/bin/env bash
# Throwaway EMPTY secret files so `docker compose config -q` works in a tree that has never run `make dev-up`.
#
# docker-compose.yml lists env_file entries under .dev/ (generated by scripts/dev-up.sh). Compose before 2.24 and the
# `-q` form of `config` in later versions (v2.38.2 on GitHub's ubuntu-latest, 2026-10) fail when such a file is missing,
# even with --no-env-resolution. Static checks (CI's deploy job, scripts/quality.sh deploy, scripts/dev-pull.sh) call
#
#   scripts/dev-placeholders.sh create     creates the missing files, EMPTY, and remembers which ones it made
#   scripts/dev-placeholders.sh remove     deletes exactly those (and .dev/ if it made it and it is empty again)
#
# An existing file is never touched. dev-up.sh treats an empty file as absent and generates real secrets into it, so a
# leftover placeholder cannot weaken anything. Nothing secret is read or printed here.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
dir=.dev
list="$dir/.placeholders"
names="controlplane dsn grafana kafka metrics postgres redis"

case "${1:-}" in
  create)
    made_dir=0
    if [ ! -d "$dir" ]; then (umask 077 && mkdir -p "$dir"); made_dir=1; fi
    for n in $names; do
      f="$dir/$n.env"
      if [ ! -e "$f" ]; then
        (umask 077 && : >"$f")
        echo "$f" >>"$list"
      fi
    done
    [ "$made_dir" = 1 ] && echo "$dir" >>"$list"
    exit 0
    ;;
  remove)
    [ -f "$list" ] || exit 0
    while IFS= read -r f; do
      if [ "$f" = "$dir" ]; then continue; fi
      [ -s "$f" ] || rm -f "$f" # a file that has since been filled with real secrets stays
    done <"$list"
    if grep -qx "$dir" "$list"; then
      rm -f "$list"
      rmdir "$dir" 2>/dev/null || true
    else
      rm -f "$list"
    fi
    exit 0
    ;;
  *)
    echo "usage: $0 create|remove" >&2
    exit 2
    ;;
esac
